-08-28 18:41:50'),
('Abandoned Cart Email Sample 3', 0, 9999, 7, 'ckeditor', '', '<meta content=\"text/html; charset=utf-8\" http-equiv=\"Content-Type\" />\n<table bgcolor=\"#F7F9FB\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#F7F9FB;\" width=\"100%\">\n	<tbody>\n		<tr style=\"height:20px;\">\n			<td style=\"padding: 20px;\">&nbsp;</td>\n		</tr>\n		<tr>\n			<td>\n			<table align=\"center\" bgcolor=\"#ffffff\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"width: 100%; max-width:600px; background-color:#FFFFFF;\">\n				<tbody>\n					<tr>\n						<td bgcolor=\"#C4670A\" style=\"padding: 40px 30px 20px 30px;\">\n						<table align=\"left\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"width: 100%; max-width: 425px;\">\n							<tbody>\n								<tr>\n									<td height=\"70\">\n									<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n										<tbody>\n											<tr>\n												<td class=\"h1\" style=\"padding: 5px 0 0 0; color: #ffffff; font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif; font-size: 33px; line-height: 38px; font-weight: bold;\"><img alt=\"logo\" src=\"{store_url}image/catalog/hb_cart/opencart-pro-logo.png\" /></td>\n											</tr>\n										</tbody>\n									</table>\n									</td>\n								</tr>\n							</tbody>\n						</table>\n						</td>\n					</tr>\n					<tr>\n						<td style=\"padding: 30px 30px 30px 30px; border-bottom: 1px solid #f2eeed;\">\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n							<tbody>\n								<tr>\n									<td style=\"font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px; line-height: 26px;\">\n									<table cellpadding=\"0\" cellspacing=\"0\" role=\"presentation\" style=\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px;\" width=\"100%\">\n										<tbody>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"padding:0;Margin:0;padding-bottom:10px;padding-top:15px;\">\n												<h1 style=\"Margin:0;line-height:58px;mso-line-height-rule:exactly;font-family:\'open sans\', \'helvetica neue\', helvetica, arial, sans-serif;font-size:48px;font-style:normal;font-weight:normal;color:#333333;\">Still thinking about it?</h1>\n												</td>\n											</tr>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"padding:0;Margin:0;padding-bottom:5px;\">\n												<p style=\"Margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:18px;font-family:lato, \'helvetica neue\', helvetica, arial, sans-serif;line-height:27px;color:#98999B;\">If you still can&rsquo;t decided, check out the reviews of recent purchasers.</p>\n												</td>\n											</tr>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"padding:0;Margin:0;padding-top:10px;\">\n												<p style=\"Margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:16px;font-family:lato, \'helvetica neue\', helvetica, arial, sans-serif;line-height:24px;color:#DD2B0D;\">{sold}</p>\n												</td>\n											</tr>\n										</tbody>\n									</table>\n									&nbsp;\n\n									<p align=\"center\" style=\"text-align: center; Margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:14px;font-family:tahoma, verdana, segoe, sans-serif;line-height:21px;color:#333333;\">{customer_reviews}</p>\n									&nbsp;\n\n									<p align=\"center\" style=\"text-align: center; Margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:14px;font-family:tahoma, verdana, segoe, sans-serif;line-height:21px;color:#333333;\">{cart_items}</p>\n									&nbsp;\n\n									<table cellpadding=\"0\" cellspacing=\"0\" role=\"presentation\" style=\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px;\" width=\"100%\">\n										<tbody>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"padding:0;Margin:0;padding-top:15px;\">\n												<h1 style=\"Margin:0;line-height:72px;mso-line-height-rule:exactly;font-family:\'playfair display\', georgia, \'times new roman\', serif;font-size:60px;font-style:normal;font-weight:normal;color:#000000;\">Hurry!</h1>\n												</td>\n											</tr>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"padding:0;Margin:0;padding-bottom:10px;\">\n												<p style=\"Margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:18px;font-family:\'open sans\', \'helvetica neue\', helvetica, arial, sans-serif;line-height:22px;color:#366E57;\">Limited stock available.</p>\n												</td>\n											</tr>\n											<tr style=\"border-collapse:collapse;\">\n												<td align=\"center\" style=\"Margin:0;padding-bottom:10px;padding-left:10px;padding-right:10px;padding-top:15px;\"><span style=\"border-style:solid;border-color:transparent;background:#366E57;border-width:0px;display:inline-block;border-radius:22px;width:auto;\"><a href=\"{checkout}\" style=\"mso-style-priority:100 !important;text-decoration:none;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-family:lato, \'helvetica neue\', helvetica, arial, sans-serif;font-size:13px;color:#FFFFFF;border-style:solid;border-color:#366E57;border-width:10px 25px 10px 25px;display:inline-block;background:#366E57;border-radius:22px;font-weight:normal;font-style:normal;line-height:16px;width:auto;text-align:center;\" target=\"_blank\">Grab It Now</a></span></td>\n											</tr>\n										</tbody>\n									</table>\n\n									<p>&nbsp;</p>\n									</td>\n								</tr>\n							</tbody>\n						</table>\n						</td>\n					</tr>\n					<tr>\n						<td bgcolor=\"#FFFFFF\" style=\"padding: 20px 30px 15px 30px;\">\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n							<tbody>\n								<tr>\n									<td align=\"center\" style=\"font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size:12px;color:#3c4043;line-height:26px;\">{store_url} &copy; 2020</td>\n								</tr>\n							</tbody>\n						</table>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</td>\n		</tr>\n		<tr style=\"height:20px;\">\n			<td style=\"padding: 20px; text-align: center;\">{email_view_tracking_pixel}</td>\n		</tr>\n	</tbody>\n</table>\n', '', '{\"sender_name\":\"{config_name}\",\"sender_email\":\"{config_email}\",\"email_bcc\":\"\",\"email_replyto\":\"\",\"email_subject\":\"{product_name} is selling fast: Complete your purchase now\",\"email_type_id\":\"2\"}', '', '2022-08-27 16:43:39', '2022-08-28 18:39:21'),
('Abandoned Cart Email Sample 2', 0, 9999, 7, 'ckeditor', '', '<meta content=\"text/html; charset=utf-8\" http-equiv=\"Content-Type\" />\n<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\" />\n<title></title>\n<div style=\"overflow: hidden;\">\n<div style=\"background:#fff;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 16px;color:#222;\">\n<div style=\"background:#F7F9FB;padding:0 2% 2%\">\n<div>&nbsp;</div>\n\n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-repeat:repeat;background-position:center;\" width=\"100%\">\n	<tbody>\n		<tr style=\"height:10px;\">\n			<td style=\"padding: 10px;\">&nbsp;</td>\n		</tr>\n		<tr>\n			<td align=\"center\">\n			<div style=\"max-width:600px\">\n			<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"text-align:left;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 14px; color:#222;width:100%\">\n				<tbody>\n					<tr>\n						<td colspan=\"3\" style=\"text-align: center; padding: 12px;\"><img alt=\"logo\" src=\"{store_url}image/catalog/hb_cart/opencart-pro-logo.png\" /></td>\n					</tr>\n					<tr>\n						<td>\n						<div style=\"background:#FFFFFF;padding:3.5%;border:1px solid #238885\">\n						<h2 style=\"text-align: left; margin-top: 7px; margin-bottom: 14px; font-size: 20px; line-height: 28px; font-weight: normal;\"><span style=\"color: rgb(0, 0, 0); font-family: arial, helvetica, verdana, sans-serif; font-size: 18px; line-height: normal; font-style: italic;\">It&#39;s in your cart! Don&#39;t forget!</span></h2>\n\n						<p style=\"min-height:1px;margin-top:0;margin-bottom:14px;border-top:1px solid #e5e5e5;text-align:right;line-height:0\">&nbsp;</p>\n\n						<h4 style=\"text-align: left;\"><b>Hello&nbsp;</b><span style=\"font-weight: bold;\">{firstname}</span></h4>\n\n						<h4 style=\"text-align: left;\"><span style=\"font-weight: bold;\"></span></h4>\n\n						<p align=\"center\" style=\"text-align: left;\">We noticed that you have recently visited our website and we wouldn&#39;t want you to miss out on the items you have in your shopping cart. If you experienced any problems placing your order then please contact our customer care at {config_telephone}</p>\n\n						<p align=\"center\" style=\"text-align: left;\">{coupon_block_start}<br />\n						Get {coupon_discount} off for minimum purchase of {coupon_minimum}. Use Coupon Code<strong> {coupon} </strong></p>\n\n						<p align=\"center\" style=\"text-align: left;\">Offer expires by {coupon_expiry}<br />\n						{coupon_block_end}<br />\n						&nbsp;</p>\n\n						<p align=\"center\" style=\"text-align: left;\">{cart_items}</p>\n\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse:collapse!important;border:0px\">\n							<tbody>\n								<tr>\n									<td align=\"center\" bgcolor=\"#4B894F\" style=\"margin:0;height:40px;width:213px\" valign=\"middle\"><a href=\"{checkout}\" style=\"background-color:#4B894F;margin:0;text-decoration:none;text-transform:uppercase;font-family:\'Roboto\',Arial,sans-serif;font-weight:500;font-size:13px;color:#ffffff;display:inline-block\" target=\"_blank\"><span style=\"display:block;width:213px;line-height:40px\">Complete Checkout</span> </a></td>\n								</tr>\n							</tbody>\n						</table>\n\n						<p align=\"center\" style=\"text-align: center;\">&nbsp;</p>\n						</div>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			</td>\n		</tr>\n	</tbody>\n</table>\n</div>\n</div>\n\n<table bgcolor=\"#F7F9FB\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n	<tbody>\n		<tr>\n			<td align=\"center\">\n			<div style=\"background: #238885;color:#999;text-align:center;font-family:Google Sans,Roboto,Helvetica,Arial,sans-serif;font-size: 12px;line-height:1.4em;max-width:600\">\n			<p style=\"text-decoration:none;color:#fff;display:inline-block;padding-bottom:20px;padding-top:20px\">All Rights Reserved | {store_url}</p>\n\n			<p style=\"text-decoration:none;color:#fff;display:inline-block;padding-bottom:20px;padding-top:20px\">&nbsp;</p>\n			</div>\n			</td>\n		</tr>\n	</tbody>\n</table>\n\n<div style=\"background:#F7F9FB;text-align: center;padding:0 2% 2%\">{email_view_tracking_pixel}</div>\n</div>\n', '', '{\"sender_name\":\"{config_name}\",\"sender_email\":\"{config_email}\",\"email_bcc\":\"\",\"email_replyto\":\"\",\"email_subject\":\"{firstname}, complete your purchase of {product_name}\",\"email_type_id\":\"2\"}', '', '2022-08-28 13:12:31', '2022-08-28 18:45:45');